function openSettings(){if(panel==='settings'||panel==='abort'||panel==='completion')return;previousPanel=panel;draft=structuredClone(settings);setPanel('settings');}
function announceRadioRecipient(recipient:RadioRecipient|null){audio.unlock();const line=radioCallout(sim.mission.companions??[],recipient);if(line)void audio.sayRadio([{line}],'solemn');else void audio.radioSquelch();}
