function updateTargetMarkers(){
 const target=sim.target,bracket=$('#targetBracket'),direction=$('#targetDirection');
 bracket.hidden=true;direction.hidden=true;
 const hudRect=$('#flightHud').getBoundingClientRect(),rect=canvas.getBoundingClientRect();
 $('#reticle').style.top=`${rect.top+rect.height/2-hudRect.top}px`;
 if(!target)return;
  const projection=world.projectTarget(target);
  if(projection.visible){
    const x=rect.left+projection.x*rect.width-hudRect.left,y=rect.top+projection.y*rect.height-hudRect.top;
    if(x>12&&x<hudRect.width-12&&y>12&&y<hudRect.height*.74){
      bracket.hidden=false;bracket.style.left=`${x}px`;bracket.style.top=`${y}px`;
      bracket.style.width=`${Math.max(25,Math.min(170,projection.size*rect.height*.8))}px`;bracket.style.height=`${Math.max(25,Math.min(180,projection.size*rect.height))}px`;
    }
  }
  if(bracket.hidden){direction.hidden=false;direction.className=projection.side;direction.textContent=`${projection.side==='left'?'◀':'▶'} ${Math.round(distance(target,sim.player))} m`;}
}
